    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == target_value and (r, c) not in visited:
                q = [(r, c)]
                visited.add((r, c))
                cells = []
                while q:
                    cr, cc = q.pop(0)
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
